// ─────────────────────────────────────────────────────────────────────
// Node: Verify Signature & Normalize Event    Mode: Run Once for All Items
// Repo: n8n-hubspot-partnerstack-deal-attribution-sync · dhRobin Systems
// Authentication (fails closed, PARTNERSTACK_AUTH_MODES):
//   hmac_sha256  X-Attribution-Signature: sha256=HMAC(secret, "<ts>.<raw body>")
//                with X-Attribution-Timestamp inside the replay window. Used when
//                a relay (or gateway) signs PartnerStack deliveries.
//   url_token    PartnerStack's webhook API takes only a target URL and events,
//                so direct deliveries are authenticated by a secret query
//                parameter (?key=...) compared in constant time.
// Normalisation: event name (dot or underscore form, or inferred), envelope,
// partner key, program type and tier from the partner group, amounts,
// timestamps, customer domain, and an idempotency key.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const helpers = this.helpers;
let crypto = null;
try { crypto = require('crypto'); } catch (error) { crypto = null; }

const SANDBOX_MODE = flag('SANDBOX_MODE', true);
const DRY_RUN = flag('DRY_RUN', true);
const PERSIST = !SANDBOX_MODE && !DRY_RUN;
const AUTH_MODES = new Set(csv('PARTNERSTACK_AUTH_MODES', 'hmac_sha256,url_token').map((m) => m.toLowerCase()));
const SIG_HEADER = env('ATTRIBUTION_SIGNATURE_HEADER', 'x-attribution-signature').toLowerCase();
const TS_HEADER = env('ATTRIBUTION_TIMESTAMP_HEADER', 'x-attribution-timestamp').toLowerCase();
const TOKEN_PARAM = env('PARTNERSTACK_URL_TOKEN_PARAM', 'key');
const TOLERANCE = Math.max(30, num('SIGNATURE_TOLERANCE_SECONDS', 300));
const SANDBOX_SECRET = 'sandbox-fictional-partnerstack-secret-not-for-production';
const SECRET = env('PARTNERSTACK_WEBHOOK_SECRET', '') || (SANDBOX_MODE ? SANDBOX_SECRET : '');
const EVENT_TYPES = new Set(csv('PROCESS_EVENT_TYPES', 'deal.created,deal.updated,deal.stage_updated,customer.created,customer.updated,transaction.created,partnership.created,partnership.updated'));
const LEDGER_DAYS = Math.max(1, num('EVENT_LEDGER_DAYS', 45));
const CENTS = flag('TRANSACTION_AMOUNT_IN_CENTS', true);
const DOMAIN_META = csv('DEAL_DOMAIN_META_KEYS', 'company_domain,domain,website,company_website').map((k) => k.toLowerCase());
const EMAIL_META = csv('DEAL_EMAIL_META_KEYS', 'contact_email,email,customer_email').map((k) => k.toLowerCase());
const FREE = new Set(['gmail.com', 'googlemail.com', 'outlook.com', 'hotmail.com', 'live.com', 'yahoo.com', 'icloud.com', 'me.com', 'aol.com', 'proton.me', 'protonmail.com', 'gmx.com']);

let runId;
try { runId = 'ps_' + crypto.randomUUID(); } catch (error) { runId = 'ps_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
const run = { runId, startedAt: new Date().toISOString(), mode: SANDBOX_MODE ? 'sandbox' : DRY_RUN ? 'dry_run' : 'live', sandboxMode: SANDBOX_MODE, dryRun: DRY_RUN };
const items = $input.all();
const sharedFixtures = SANDBOX_MODE ? ((items.find((i) => i.json.sandboxFixtures) || { json: {} }).json.sandboxFixtures || null) : null;

const sha = (s) => crypto.createHash('sha256').update(String(s)).digest();
const safeEqual = (a, b) => !!crypto && typeof a === 'string' && typeof b === 'string' && a.length > 0 && b.length > 0 && crypto.timingSafeEqual(sha(a), sha(b));

function authenticate(headers, query, raw) {
  if (!crypto) return { ok: false, reason: 'crypto_module_unavailable' };
  if (!SECRET) return { ok: false, reason: 'webhook_secret_not_configured' };
  if (headers[SIG_HEADER] !== undefined) {
    if (!AUTH_MODES.has('hmac_sha256')) return { ok: false, method: 'hmac_sha256', reason: 'hmac_mode_disabled' };
    const provided = String(headers[SIG_HEADER]).replace(/^sha256=/i, '').trim();
    const ts = String(headers[TS_HEADER] || '').trim();
    if (!/^\d{10,13}$/.test(ts)) return { ok: false, method: 'hmac_sha256', reason: 'timestamp_header_missing' };
    const digest = crypto.createHmac('sha256', SECRET).update(`${ts}.${raw}`, 'utf8').digest();
    if (!(safeEqual(provided.toLowerCase(), digest.toString('hex')) || safeEqual(provided, digest.toString('base64')))) return { ok: false, method: 'hmac_sha256', reason: 'signature_mismatch' };
    const tsSec = ts.length > 10 ? Math.floor(Number(ts) / 1000) : Number(ts);
    if (!SANDBOX_MODE && Math.abs(Date.now() / 1000 - tsSec) > TOLERANCE) return { ok: false, method: 'hmac_sha256', reason: 'timestamp_outside_tolerance' };
    return { ok: true, method: 'hmac_sha256' };
  }
  if (!AUTH_MODES.has('url_token')) return { ok: false, method: 'hmac_sha256', reason: 'signature_header_missing' };
  const provided = query[TOKEN_PARAM] !== undefined ? String(query[TOKEN_PARAM]) : '';
  if (!provided) return { ok: false, method: 'url_token', reason: 'url_token_missing' };
  return safeEqual(provided, SECRET) ? { ok: true, method: 'url_token' } : { ok: false, method: 'url_token', reason: 'url_token_mismatch' };
}

const toIso = (v) => { if (v === null || v === undefined || v === '') return null; const n = Number(v); const d = Number.isFinite(n) ? new Date(n < 1e12 ? n * 1000 : n) : new Date(String(v)); return Number.isNaN(d.getTime()) ? null : d.toISOString(); };
const toMs = (v) => { const iso = toIso(v); return iso ? Date.parse(iso) : null; };
const money = (v, cents) => { const n = Number(v); return Number.isFinite(n) ? Math.round((cents ? n / 100 : n) * 100) / 100 : null; };
const domainOf = (v) => {
  if (!v) return null;
  let s = String(v).trim().toLowerCase();
  if (s.includes('@')) s = s.split('@').pop();
  s = s.replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split(/[/?#:]/)[0];
  return /^[a-z0-9-]+(\.[a-z0-9-]+)+$/.test(s) && !FREE.has(s) ? s : null;
};
const email = (v) => { const s = String(v || '').trim().toLowerCase(); return /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(s) ? s : null; };
const metaValue = (meta, prefixes) => {
  if (!meta || typeof meta !== 'object') return null;
  // PartnerStack custom-field keys carry a random suffix (company_name_38n83e3e3), so match by prefix.
  for (const [k, v] of Object.entries(meta)) { const key = k.toLowerCase(); if (v && prefixes.some((p) => key === p || key.startsWith(`${p}_`))) return String(v); }
  return null;
};
const programFromGroup = (g) => {
  if (!g) return null;
  const text = `${g.slug || ''} ${g.name || ''}`.toLowerCase();
  const programType = /resell|var\b|distribut/.test(text) ? 'reseller' : /affiliat|influenc|creator/.test(text) ? 'affiliate' : 'referral';
  const m = text.match(/platinum|gold|silver|bronze|tier[-_ ]?(\d)/);
  return { programType, tier: m ? (m[1] ? `tier_${m[1]}` : m[0]) : null, groupSlug: g.slug ? String(g.slug).slice(0, 80) : null, groupName: g.name ? String(g.name).slice(0, 120) : null };
};
function inferType(d) {
  if (d.stage !== undefined && d.partner_key !== undefined) return 'deal';
  if (d.customer_key !== undefined && d.amount !== undefined) return 'transaction';
  if (d.group !== undefined && d.partner_key !== undefined) return 'partnership';
  if (d.email !== undefined && d.partner_key !== undefined && d.key !== undefined) return 'customer';
  return null;
}

const staticData = $getWorkflowStaticData('global');
const ledger = PERSIST ? (staticData.psAttributionLedger = staticData.psAttributionLedger || {}) : JSON.parse(JSON.stringify(staticData.psAttributionLedger || {}));
const nowMs = Date.now();
for (const [k, v] of Object.entries(ledger)) if (!v || nowMs - v.at > LEDGER_DAYS * 86400000) delete ledger[k];
const seen = new Set();

const out = [];
for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const headers = {};
  for (const [k, v] of Object.entries(item.json.headers || {})) headers[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0]) : String(v);
  const query = item.json.query || {};
  let raw = null;
  if (item.binary && item.binary.data) { try { raw = (await helpers.getBinaryDataBuffer(index, 'data')).toString('utf8'); } catch (e) { raw = null; } }
  let body = item.json.body;
  if ((!body || (typeof body === 'object' && !Object.keys(body).length)) && raw) { try { body = JSON.parse(raw); } catch (e) { body = null; } }
  if (raw === null) raw = typeof body === 'string' ? body : JSON.stringify(body ?? {});
  if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = null; } }
  const base = { run, sandboxFixtures: sharedFixtures, deliveryRef: `delivery-${index + 1}` };

  const auth = authenticate(headers, query, raw);
  if (!auth.ok) { out.push({ json: { ...base, kind: 'rejected', reason: auth.reason, authMethod: auth.method || null } }); continue; }
  const b = body && typeof body === 'object' ? body : {};
  const d = b.data && typeof b.data === 'object' && !Array.isArray(b.data) && (b.event || b.type) ? b.data : b;
  let eventName = String(b.event || b.type || query.event || headers['x-partnerstack-event'] || '').trim().toLowerCase();
  if (eventName) eventName = eventName.replace(/^(deal|customer|transaction|partnership|lead|reward|action|message)_/, '$1.').replace('deal.stage_update', 'deal.stage_updated').replace('deal.stage_updated', 'deal.stage_updated');
  const objectType = eventName ? eventName.split('.')[0] : inferType(d);
  if (!eventName && objectType) eventName = `${objectType}.updated`;
  const ignore = (reason) => out.push({ json: { ...base, kind: 'ignored', reason, authMethod: auth.method, event: { name: eventName || null, objectKey: d.key ? String(d.key).slice(0, 80) : null } } });
  if (!eventName || !objectType) { ignore('event_type_unknown'); continue; }
  if (!EVENT_TYPES.has(eventName)) { ignore('event_type_not_processed'); continue; }
  if (d.archived === true || d.archived === 'true') { if (objectType !== 'partnership') { ignore('archived_record'); continue; } }

  const objectKey = d.key ? String(d.key).slice(0, 80) : objectType === 'partnership' && d.partner_key ? `partner:${d.partner_key}` : null;
  if (!objectKey) { ignore('missing_object_key'); continue; }
  const updatedMs = toMs(d.updated_at) || toMs(d.created_at) || nowMs;
  const dedupeKey = `${eventName}:${objectKey}:${updatedMs}`;
  if (seen.has(dedupeKey) || ledger[dedupeKey]) { ignore('duplicate_event'); continue; }
  seen.add(dedupeKey);

  const ev = { name: eventName, objectType, action: eventName.split('.').slice(1).join('.'), objectKey, partnerKey: d.partner_key ? String(d.partner_key).slice(0, 80) : null, occurredAt: new Date(updatedMs).toISOString(), occurredMs: updatedMs, createdAt: toIso(d.created_at) };
  let record = {};
  if (objectType === 'deal') {
    const contactEmail = email(metaValue(d.meta, EMAIL_META));
    record = { accountName: d.account_name ? String(d.account_name).slice(0, 160) : null, amount: money(d.amount, false), closeDate: toIso(d.close_date), stage: d.stage ? String(d.stage).slice(0, 60) : null,
      customerDomain: domainOf(metaValue(d.meta, DOMAIN_META)) || domainOf(contactEmail), customerEmail: contactEmail, psCompanyId: d.company_id != null ? String(d.company_id) : null };
  } else if (objectType === 'customer') {
    const e = email(d.email);
    record = { customerKey: objectKey, customerEmail: e, customerDomain: domainOf(e), customerName: d.name ? String(d.name).slice(0, 160) : null };
  } else if (objectType === 'transaction') {
    record = { transactionKey: objectKey, customerKey: d.customer_key ? String(d.customer_key).slice(0, 80) : null, amount: money(d.amount, CENTS), currency: d.currency ? String(d.currency).toUpperCase().slice(0, 3) : null };
  } else if (objectType === 'partnership') {
    const e = email(d.email);
    record = { partnerEmailDomain: domainOf(e), partnerEmail: e, archived: d.archived === true || d.archived === 'true', program: programFromGroup(d.group) };
  }
  if (!ev.partnerKey && objectType !== 'transaction') { ignore('no_partner_key'); continue; }
  out.push({ json: { ...base, kind: 'event', authMethod: auth.method, dedupeKey, event: ev, record } });
}
return out;

// ─────────────────────────────────────────────────────────────────────
// Node: Build Lookup Plan                     Mode: Run Once for Each Item
// HubSpot searches for the partner company, the customer company and the
// customer contact. Searches that don't apply get a no-result filter, so
// the live chain stays linear for every event type.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const P = env('PS_PROPERTY_PREFIX', 'ps_');
const item = $json; const ev = item.event; const r = item.record;
const noop = { filterGroups: [{ filters: [{ propertyName: 'hs_object_id', operator: 'EQ', value: '0' }] }], limit: 1 };
const eq = (p, v) => ({ filters: [{ propertyName: p, operator: 'EQ', value: v }] });
const partnerProps = ['name', 'domain', `${P}partner_key`, `${P}partner_tier`, `${P}program_type`, `${P}commission_rate`, `${P}partner_status`];
const companyProps = ['name', 'domain', 'hubspot_owner_id', `${P}partner_key`, `${P}customer_key`, `${P}attribution_status`, `${P}referred_at`, `${P}last_transaction_key`, `${P}partner_sourced_revenue`];
const groupsPartner = [];
if (ev.partnerKey) groupsPartner.push(eq(`${P}partner_key`, ev.partnerKey));
if (ev.objectType === 'partnership' && r.partnerEmailDomain) groupsPartner.push(eq('domain', r.partnerEmailDomain), eq('domain', `www.${r.partnerEmailDomain}`));
let company = noop; let contact = noop;
if ((ev.objectType === 'deal' || ev.objectType === 'customer') && r.customerDomain) company = { filterGroups: [eq('domain', r.customerDomain), eq('domain', `www.${r.customerDomain}`)], properties: companyProps, limit: 10 };
if (ev.objectType === 'transaction' && r.customerKey) { company = { filterGroups: [eq(`${P}customer_key`, r.customerKey)], properties: companyProps, limit: 5 }; contact = { filterGroups: [eq(`${P}customer_key`, r.customerKey)], properties: ['email', 'associatedcompanyid', `${P}partner_key`, `${P}customer_key`], limit: 5 }; }
if ((ev.objectType === 'customer' || ev.objectType === 'deal') && r.customerEmail) contact = { filterGroups: [eq('email', r.customerEmail)], properties: ['email', 'associatedcompanyid', `${P}partner_key`, `${P}customer_key`], limit: 5 };
return { json: { ...item, lookup: { prefix: P, partnerCompany: groupsPartner.length ? { filterGroups: groupsPartner.slice(0, 5), properties: partnerProps, limit: 10 } : noop, company, contact, noop } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Simulate HubSpot Lookups (Sandbox)    Mode: Run Once for Each Item
// Answers every live search from fictional fixtures, in the CRM search
// (and PartnerStack partnership) response shapes.
// ─────────────────────────────────────────────────────────────────────
const item = $json; const fx = item.sandboxFixtures || {}; const P = item.lookup.prefix;
const ev = item.event; const r = item.record;
const ok = (list) => ({ statusCode: 200, body: { total: list.length, results: list.map((x) => ({ id: x.id, properties: x.properties })) } });
const norm = (v) => String(v || '').toLowerCase().replace(/^www\./, '');
const companies = fx.companies || [];
const partner = companies.filter((c) => (ev.partnerKey && c.properties[`${P}partner_key`] === ev.partnerKey) || (ev.objectType === 'partnership' && r.partnerEmailDomain && norm(c.properties.domain) === r.partnerEmailDomain));
let customer = [];
if ((ev.objectType === 'deal' || ev.objectType === 'customer') && r.customerDomain) customer = companies.filter((c) => norm(c.properties.domain) === r.customerDomain);
if (ev.objectType === 'transaction' && r.customerKey) customer = companies.filter((c) => c.properties[`${P}customer_key`] === r.customerKey);
const contacts = (fx.contacts || []).filter((c) => (r.customerEmail && c.properties.email === r.customerEmail) || (ev.objectType === 'transaction' && r.customerKey && c.properties[`${P}customer_key`] === r.customerKey));
const cid = customer[0] ? customer[0].id : null;
const deals = ev.objectType === 'partnership' ? [] : (fx.deals || []).filter((d) => (ev.objectType === 'deal' && d.properties[`${P}deal_key`] === ev.objectKey) || (cid && d.companyId === cid));
const ps = (fx.partnerships || {})[ev.partnerKey];
return { json: { ...item, simulatedLookup: { partnerCompany: ok(partner), company: ok(customer), contact: ok(contacts), deals: ok(deals),
  partnership: ps ? { statusCode: 200, body: { data: ps } } : null } } };

// ─────────────────────────────────────────────────────────────────────
// Node: Pick Records & Build Deal Search      Mode: Run Once for Each Item
// Chooses the partner company, customer company and contact, then builds
// the deal search: by PartnerStack deal key, or deals on the customer company.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
const num = (key, fallback) => {
  const raw = env(key, '');
  const n = Number(raw);
  return raw !== '' && Number.isFinite(n) ? n : fallback;
};
const csv = (key, fallback = '') => env(key, fallback).split(',').map((s) => s.trim()).filter(Boolean);

const placeholder = (v) => !v || /^YOUR_/i.test(String(v));
const ENRICH = flag('PARTNERSTACK_ENRICH_PARTNER', true) && !placeholder(env('PARTNERSTACK_API_KEY', '')) && !placeholder(env('PARTNERSTACK_PUBLIC_KEY', ''));
const sandbox = !!($json && $json.simulatedLookup);
let ctx; let res;
if (sandbox) { ctx = $json; res = ctx.simulatedLookup; }
else {
  ctx = $('Build Lookup Plan').item.json;
  res = { partnerCompany: $('Search Partner Company').item.json, company: $('Search Customer Company').item.json, contact: $json };
}
const P = ctx.lookup.prefix; const ev = ctx.event; const r = ctx.record;
const errors = [];
const list = (name, x, used) => { if (!used) return []; if (Number(x && x.statusCode) !== 200 || !x.body || !Array.isArray(x.body.results)) { errors.push(`${name} search ${(x && x.statusCode) || 'network error'}`); return []; } return x.body.results; };
const isNoop = (b) => JSON.stringify(b) === JSON.stringify(ctx.lookup.noop);
const norm = (v) => String(v || '').toLowerCase().replace(/^[a-z]+:\/\//, '').replace(/^www\./, '').split('/')[0];
const slim = (x) => (x ? { id: String(x.id), properties: x.properties || {} } : null);

const partners = list('partner company', res.partnerCompany, !isNoop(ctx.lookup.partnerCompany));
const partnerCompany = slim(partners.find((c) => (c.properties || {})[`${P}partner_key`] === ev.partnerKey) || partners.find((c) => r.partnerEmailDomain && norm(c.properties.domain) === r.partnerEmailDomain));
const companies = list('customer company', res.company, !isNoop(ctx.lookup.company));
const exact = companies.filter((c) => (r.customerDomain && norm(c.properties.domain) === r.customerDomain) || (r.customerKey && c.properties[`${P}customer_key`] === r.customerKey));
const contacts = list('contact', res.contact, !isNoop(ctx.lookup.contact));
const contact = slim(contacts[0]);
let customerCompany = slim(exact[0]);
let companySource = customerCompany ? (r.customerKey && ev.objectType === 'transaction' ? 'customer_key' : 'domain') : null;
if (!customerCompany && contact && contact.properties.associatedcompanyid) { customerCompany = { id: String(contact.properties.associatedcompanyid), properties: {} }; companySource = 'contact_primary_company'; }

const dealGroups = [];
if (ev.objectType === 'deal') dealGroups.push({ filters: [{ propertyName: `${P}deal_key`, operator: 'EQ', value: ev.objectKey }] });
if (customerCompany && ev.objectType !== 'partnership' && ev.objectType !== 'customer') dealGroups.push({ filters: [{ propertyName: 'associations.company', operator: 'EQ', value: customerCompany.id }] });
const dealProps = ['dealname', 'dealstage', 'amount', 'closedate', 'hs_is_closed', 'hs_is_closed_won', 'hs_lastmodifieddate', 'hubspot_owner_id',
  ...['deal_key', 'partner_key', 'attribution_status', 'commission_status', 'estimated_commission', 'partner_sourced_revenue', 'last_transaction_key', 'last_event_at', 'won_at'].map((p) => `${P}${p}`)];
const { simulatedLookup, ...rest } = ctx;
return {
  json: {
    ...rest,
    ...(sandbox ? { simulatedLookup } : {}),
    picked: { partnerCompany, customerCompany, companySource, contact, customerCompanyCount: exact.length, errors },
    enrichPartner: !sandbox && ENRICH && !!ev.partnerKey,
    searches: { deals: dealGroups.length ? { filterGroups: dealGroups, properties: dealProps, sorts: [{ propertyName: 'hs_lastmodifieddate', direction: 'DESCENDING' }], limit: 20 } : ctx.lookup.noop },
  },
};

// ─────────────────────────────────────────────────────────────────────
// Node: Resolve Attribution                   Mode: Run Once for Each Item
// Partner program: partnership event group → PartnerStack API group →
// HubSpot partner company properties → DEFAULT_PROGRAM_TYPE.
// Deal: exact PartnerStack deal key → the customer company's single open
// deal (or best name/amount match) for registrations, its won deal for
// transactions. Ties are never auto-resolved.
// Guards: stale events, already-applied transactions, attribution
// conflicts (first-touch by default) and suspected self-referrals.
// ─────────────────────────────────────────────────────────────────────
const env = (key, fallback = '') => {
  try {
    const value = $env[key];
    return value === undefined || value === null || String(value).trim() === '' ? fallback : String(value).trim();
  } catch (error) {
    return fallback; // env access blocked -> safe defaults apply
  }
};
const flag = (key, fallback) => {
  const v = env(key, '').toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return fallback; // unrecognised values keep the safe default
};
